import sqlite3
from contextlib import contextmanager

DB_PATH = "poligony.db"

def init_db():
    with sqlite3.connect(DB_PATH) as conn:
        with open("schema.sql") as f:
            conn.executescript(f.read())

@contextmanager
def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row  # dostep do kolumn po nazwie, nie tylko indeksie
    try:
        yield conn
    finally:
        conn.close()
conn.row_factory = sqlite3.Row sprawia, że wiersze zwrócone z zapytań zachowują się trochę jak słowniki (row["nazwa"]), zamiast gołych krotek (row[1]) — dużo czytelniej przy konwersji na model Pydantic.
Wywołaj init_db() raz, przy starcie aplikacji:
@app.on_event("startup")
def startup():
    init_db()

